#!/usr/bin/env node
/**
 * Single-file outputs, for looking at the console without a toolchain.
 *
 * Both are GENERATED from src/ and seed/, never hand-written. That matters:
 * a hand-written preview of eleven modules is a second implementation, it
 * drifts from the real one within a week, and someone clicks it and believes
 * what they saw. These are build artifacts, like seed/network-scan.json —
 * regenerate them, do not edit them.
 *
 *   dist/command-center.jsx   The whole console as one readable JSX file, with
 *                             every seed inlined and types stripped. React
 *                             stays external. Paste it where JSX is what runs.
 *   dist/command-center.css   The stylesheet the .jsx expects beside it.
 *   dist/command-center.html  The console as one self-contained page. No
 *                             server, no install, no network — open it.
 *
 * The HTML output keeps the same guarantees as the app: noindex, a content
 * security policy, and no external origin. Its inline script is allowed by
 * sha256 hash rather than by 'unsafe-inline', so the policy stays as tight as
 * the served page's.
 */
import { build } from 'esbuild'
import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'

mkdirSync('dist', { recursive: true })

// ── 1. Readable JSX, seeds inlined, React left external ───────────────────

await build({
  entryPoints: ['src/App.tsx'],
  bundle: true,
  format: 'esm',
  jsx: 'preserve',
  // A generated artifact is a distribution build, and `import.meta.env` does
  // not exist in most places this file gets dropped. Pinning it to false picks
  // the guard's production behaviour: a blocked term renders `[redacted]`
  // rather than throwing. The term still never reaches a reader; the page just
  // does not go white to prove it.
  define: { 'import.meta.env.DEV': 'false' },
  loader: { '.json': 'json' },
  external: ['react', 'react-dom', 'react-dom/client'],
  outfile: 'dist/command-center.jsx',
  banner: {
    js: [
      '/*',
      ' * NTE-TECH-2026-CCENTER-001 — generated single-file build.',
      ' *',
      ' * Generated by scripts/bundle-single.mjs from src/ and seed/. Do not',
      ' * edit: this is an artifact, and an edit here is a change that exists',
      ' * in no register and reaches no test.',
      ' *',
      ' * Exports ModuleBody and, as default, App. Needs React 18 and',
      ' * dist/command-center.css beside it. Mount it with:',
      ' *',
      ' *   import App from \'./command-center.jsx\'',
      ' *   createRoot(document.getElementById(\'root\')).render(<App />)',
      ' *',
      ' * The enforcement layer is in here and is not decoration: the build',
      ' * freeze, the surface firewall and the proof gates all run. A blocked',
      ' * term renders [redacted] rather than throwing, which is the guard\'s',
      ' * production behaviour.',
      ' */',
    ].join('\n'),
  },
})

// esbuild names the emitted stylesheet after the outfile.
const cssPath = 'dist/command-center.css'

// ── 2. Self-contained page ────────────────────────────────────────────────

await build({
  entryPoints: ['src/main.tsx'],
  bundle: true,
  format: 'iife',
  jsx: 'automatic',
  minify: true,
  define: { 'process.env.NODE_ENV': '"production"', 'import.meta.env.DEV': 'false' },
  loader: { '.json': 'json' },
  outfile: 'dist/.single.js',
})

const js = readFileSync('dist/.single.js', 'utf8')
const css = readFileSync('dist/.single.css', 'utf8')
const hash = createHash('sha256').update(js).digest('base64')

const page = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
    <!-- Private instrument. Never indexed, never linked, never shared. -->
    <meta name="robots" content="noindex, nofollow, noarchive, nosnippet" />
    <meta name="referrer" content="no-referrer" />
    <!-- Zero external origins. The inline script is allowed by hash, not by
         'unsafe-inline' — the policy is no looser than the served page's. -->
    <meta
      http-equiv="Content-Security-Policy"
      content="default-src 'none'; script-src 'sha256-${hash}'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; font-src 'self'"
    />
    <meta name="apple-mobile-web-app-capable" content="yes" />
    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
    <title>Command Center</title>
    <style>${css}</style>
  </head>
  <body>
    <div id="root"></div>
    <script>${js}</script>
  </body>
</html>
`

writeFileSync('dist/command-center.html', page)
rmSync('dist/.single.js')
rmSync('dist/.single.css')

const kb = (s) => `${(Buffer.byteLength(s) / 1024).toFixed(1)} kB`
console.log('Single-file build:')
console.log(`  dist/command-center.jsx   ${kb(readFileSync('dist/command-center.jsx', 'utf8'))}  React external, seeds inlined`)
console.log(`  dist/command-center.css   ${kb(readFileSync(cssPath, 'utf8'))}`)
console.log(`  dist/command-center.html  ${kb(page)}  self-contained, opens offline`)
